import{_ as t,c as l,o as r,ah as a}from"./chunks/framework.Ch_PcVtW.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/output/PART2/20/0_context_summary.md","filePath":"scripts/output/PART2/20/0_context_summary.md"}'),e={name:"scripts/output/PART2/20/0_context_summary.md"};function o(n,i,s,_,u,c){return r(),l("div",null,[...i[0]||(i[0]=[a('<h2 id="_1-本篇主题与主要内容概述" tabindex="-1">1) 本篇主题与主要内容概述 <a class="header-anchor" href="#_1-本篇主题与主要内容概述" aria-label="Permalink to &quot;1) 本篇主题与主要内容概述&quot;">​</a></h2><p>本篇围绕第二届「BMSG FES」展开，重点说明将所属艺人按出身地分为「BMSG EAST」与「BMSG WEST」的原因：通过打破原有组合和关系网络，营造类似全明星赛的游戏感与非日常感，促成新的交流与化学反应。SKY-HI回顾了HAYATO、RAN、RYOKI、edhiii boi等成员在舞台上的变化，分享对成员成长、心理状态及未来发展的判断。同时，他从制作人和表演者双重视角分析演出编排，特别谈到Shota多变的魅力，以及“满足期待但不让观众猜中”的整体创作理念。</p><h2 id="_2-人物-术语-语气风险点" tabindex="-1">2) 人物/术语/语气风险点 <a class="header-anchor" href="#_2-人物-术语-语气风险点" aria-label="Permalink to &quot;2) 人物/术语/语气风险点&quot;">​</a></h2><ul><li><strong>人物与团体名称</strong>：BMSG、BE:FIRST、MAZZEL、Aile The Shota、REIKO、edhiii boi等专有名词须统一官方写法；首次出现可按原文保留英文并补充中文说明。</li><li><strong>关系值（関係値）</strong>：不是简单的“关系”，更接近成员间既有的默契、互动基础与关系网络，需结合语境翻译。</li><li><strong>EAST/WEST分组</strong>：应突出按出身地划分、打散既有组合的策划目的，避免译成普通地域分队。</li><li><strong>オールスター戦、あおり、チェイサー、ダンスサイファー、アテ書き</strong>：属于音乐、现场演出或创作术语，需准确传达行业含义。</li><li><strong>第一人称语气</strong>：整体应保留SKY-HI坦率、活跃、带有玩心的口吻；“妄信”“ゲラゲラ笑う”等表达不能过度书面化。</li><li><strong>严肃与轻松并存</strong>：成员未来、学业、驾车、商业数字等部分较为理性；涉及钱包、忘词、成员反差时则应保留幽默感。</li><li><strong>人物评价的分寸</strong>：如“少年”“かわいげ”“求爱精神”“えたいの知れない存在”等带有亲密和感情色彩，不宜翻译得过于尖锐或贬义。</li><li><strong>疑似原文/OCR错误</strong>： <ul><li>「ストロングスタイルのあおりだけでな」应核对为“ストロングスタイルのあおりだけでなく”；</li><li>「プロジリリース」疑似“プロジェクトのリリース”；</li><li>「で「きるかな？」疑似“できるかな？”；</li><li>「予想はさせハけた理由「ない」」疑似“予想はさせない”；</li><li>「といストレート」疑似“というストレート”；</li><li>「TEAMC」及相关曲名、成员归属建议结合官方资料复核。</li></ul></li></ul><h2 id="_3-翻译时建议重点" tabindex="-1">3) 翻译时建议重点 <a class="header-anchor" href="#_3-翻译时建议重点" aria-label="Permalink to &quot;3) 翻译时建议重点&quot;">​</a></h2><ul><li>以<strong>出版物级别的自然中文</strong>为目标，不逐字硬译，保持访谈体的呼吸感和现场感。</li><li>明确区分SKY-HI的主观发言与编辑部的客观说明：前者使用自然的第一人称口语，后者保持中性、准确。</li><li>“壊した”“ごちゃ混ぜにした”等表达应译出“主动打破既有关系、重新混编”的策划意识。</li><li>“新しいRAN”“みんな家族”等舞台语境中的表达，要保留其情绪冲击力，不宜弱化成普通叙述。</li><li>对《New Chapter》《14th Syndrome》《YOLO》《Brave Generation -BMSG United Remix》等曲名统一格式；英文歌词可保留英文，并视版式补充中文释义。</li><li>“期待は裏切らないけど、予想はさせない”是本篇核心创作理念，建议作为小标题译为“不会辜负期待，但不会让人猜中”。</li><li>保留括号中的补充信息，但避免层层嵌套；人物首次出现时说明身份，后文统一使用简称。</li><li>对“情绪化”“哭泣”“エモ”等表达，需在感性与出版语体之间取得平衡，避免翻译成网络化或过度煽情的语言。</li></ul>',6)])])}const m=t(e,[["render",o]]);export{d as __pageData,m as default};
